#[path="../src/remaining_types/workflow_v1.rs"]mod workflow_v1;use workflow_v1::*;
#[test]fn native_order_and_forward_recovery_preserve_durable_facts(){let success=run_scenario(false);let failure=run_scenario(true);assert_eq!(success.trace,ORDER);assert_eq!(failure.trace,ORDER[..3]);assert_eq!(failure.recovery_intents,vec!["forward-recover-settlement"]);assert!(!failure.compensation_execution);assert_eq!(failure.durable_fact_preservation,"preserve-durable-facts");let mut stale=baseline();stale.s1_binding_state="stale";assert_eq!(evaluate_s1(&stale),vec!["RMT_S1_STALE_BINDING"]);}
#[test]fn kills_all_ten_semantic_controls_as_singletons(){let mut cases:Vec<(&str,WorkflowObservation)>=Vec::new();let mut v=baseline();v.observed_step_ids=vec!["decide","validate","persist","publish"];cases.push(("RMT_WF_STEP_REORDER",v));let mut v=baseline();v.observed_step_ids.pop();cases.push(("RMT_WF_STEP_SKIP",v));let mut v=baseline();v.observed_step_ids=vec!["validate","decide","persist","persist","publish"];cases.push(("RMT_WF_STEP_DUPLICATE",v));let mut v=baseline();v.scope="cross-feature";cases.push(("RMT_WF_SCOPE_DRIFT",v));let mut v=baseline();v.failure_continuation_policy="continue";cases.push(("RMT_WF_FAILURE_CONTINUATION_MISMATCH",v));let mut v=baseline();v.recovery_intents.push("rollback");cases.push(("RMT_WF_COMPENSATION_OVERCLAIM",v));let mut v=baseline();v.direct_effects_executed.push("publish");cases.push(("RMT_WF_EXECUTES_EFFECT",v));let mut v=baseline();v.binding_state="stale";cases.push(("RMT_WF_STALE_BINDING",v));let mut v=baseline();v.guard_bypass_observed=true;cases.push(("RMT_WF_GUARD_BYPASS",v));let mut v=baseline();v.lifecycle_transition_bypass_observed=true;cases.push(("RMT_WF_LIFECYCLE_TRANSITION_BYPASS",v));assert_eq!(cases.len(),10);for(expected,observed)in cases{assert_eq!(evaluate(&observed),vec![expected],"{expected}");}}
